<?php
function mc_products(): array { static $p=null;if($p!==null)return $p;$raw=file_get_contents(dirname(__DIR__).'/data/products.json');$p=json_decode($raw?:'{}',true);return is_array($p)?$p:[]; }
function mc_normalize_cart($input): array { if(!is_array($input)||count($input)===0||count($input)>50)throw new InvalidArgumentException('Carrinho vazio ou inválido.');$products=mc_products();$out=[];foreach($input as $raw){$id=trim((string)($raw['id']??''));if(!isset($products[$id]))throw new InvalidArgumentException("Produto inválido: $id");$p=$products[$id];$q=max(1,min(100,(int)($raw['quantity']??1)));$opts=$p['options']??[];$opt=substr((string)($raw['option']??($opts[0]??'ÚNICO')),0,80);if($opts&&!in_array($opt,$opts,true))throw new InvalidArgumentException('Opção inválida para '.$p['name'].'.');$out[]=['id'=>$id,'name'=>$p['name'],'quantity'=>$q,'option'=>$opt,'priceCents'=>(int)$p['priceCents'],'image'=>$p['image']??''];}return $out; }
function mc_subtotal(array $cart): int { $s=0;foreach($cart as $i)$s+=(int)$i['priceCents']*(int)$i['quantity'];return $s; }
